import React, { useState, useEffect } from "react";
import styled from "styled-components";
import client from "../mqtt";

const Image = styled.img`
  width: 100vw;
  height: 100vh;
`;

export default () => {
  const [boost, setBoost] = useState(false);
  useEffect(() => {
    client.subscribe("boost", function (err) {});
    client.on("message", function (topic, message) {
      if (topic === "boost") {
        setBoost(!boost);
      }
    });
  });
  return (
    <>
      {!boost && (
        <Image src="https://www.simhubdash.com/wp-content/uploads/wpforo/default_attachments/1572020517-HondaS2000.gif"></Image>
      )}
      {boost && (
        <Image src="https://i.pinimg.com/originals/0f/b3/f0/0fb3f04023c0d115423b3bcccb65ef83.gif"></Image>
      )}
    </>
  );
};
