import React, { useEffect, useState } from "react";
import styled from "styled-components";
import ReactPlayer from "react-player";

import client from "../mqtt";

const Image = styled.img`
  width: 100vw;
  height: 100vh;
`;

const Player = styled(ReactPlayer)`
  width: 100vw;
  height: 100vh;
`;

export default () => {
  const [playing, setPlaying] = useState(false);
  const [volume, setVolume] = useState(0);
  const [muted, setMuted] = useState(false);
  useEffect(() => {
    client.subscribe("tape/#", function (err) {});
    client.on("message", function (topic, message) {
      if (topic === "tape/start") {
        setPlaying(true);
      }
      if (topic === "tape/stop") {
        setPlaying(false);
      }
      if (topic === "tape/volume") {
        const value = parseFloat(message.toString());
        setMuted(false);
        setVolume(value);
        console.log(message.toString());
      }
    });
  }, []);
  return (
    <>
      {!playing && (
        <Image
          src="https://thumbs.gfycat.com/MeekBeautifulCaterpillar-size_restricted.gif"
          onClick={() => {
            client.publish("control/volume/visible", "");
            setPlaying(true);
          }}
        ></Image>
      )}
      {playing && (
        <Player
          onClick={() => {
            client.publish("control/volume/invisible", "");
            setPlaying(false);
          }}
          url={"https://www.youtube.com/watch?v=OwAr6MVl8hQ"}
          playing={playing}
          volume={volume}
          muted={muted}
          loop={true}
          config={{
            youtube: {
              playerVars: { showinfo: 1 },
            },
          }}
        />
      )}
    </>
  );
};
